const j = items[0].json || {};
const body = j.body || j;
let images = Array.isArray(body.images) ? body.images.filter((x) => x && x.base64) : [];
if (!images.length && body.imageBase64) {
  images = [{ base64: body.imageBase64, mime: body.imageMime || 'image/jpeg' }];
}
if (!images.length) throw new Error('images or imageBase64 required');
return [{
  json: {
    images,
    imageBase64: images[0].base64,
    imageMime: images[0].mime || 'image/jpeg',
    note: body.note || '',
    audioBase64: body.audioBase64 || '',
    audioMime: body.audioMime || 'audio/webm',
    host: 'http://host.docker.internal:3000',
    serviceToken: $env.INTERNAL_SERVICE_TOKEN || $env.GEMINI_PROXY_TOKEN || '',
  }
}];

const res = items[0].json;
if (res.ok && res.meal) {
  return [{ json: { ok: true, meal: res.meal, model: res.model, usage: res.usage, via: 'n8n->host-app-meal-gemini' } }];
}
return [{ json: { ok: false, error: res.error || JSON.stringify(res).slice(0,400) } }];
